arguments.command:
cd /app/ssl; diff <(openssl x509 -in server.crt -noout -modulus) <(openssl rsa -in server.key -noout -modulus) && echo MATCH; openssl rsa -in server.key -noout -text | head -1
mkdir -p /tmp/noc && printf 'import sys\nsys.modules["cryptography"]=None\n' >/dev/null
python3 -c "
import builtins,runpy
real=builtins.__import__
def imp(n,*a,**k):
    if n.startswith('cryptography'): raise ImportError('blocked')
    return real(n,*a,**k)
builtins.__import__=imp
runpy.run_path('/app/check_cert.py',run_name='__main__')" ; echo "fallback_exit=$?"

